  "ajo.failedCloseCycle":             { en: "Failed to close cycle.", pidgin: "Cycle no close.", ha: "Rufe zagaye ya gaza.", ig: "Imechi okirikiri adaghị.", yo: "Títi àyíká kùnà." },
  "ajo.commissionExecutionFailed":    { en: "Commission execution failed.", pidgin: "Commission no go through.", ha: "Aiwatar da kwamishan ya gaza.", ig: "Ime kọmịshọn adaghị.", yo: "Ṣíṣe kọ́míṣọ̀n kùnà." },
  "ajo.clientAccountCreated":         { en: "Client Account Created", pidgin: "Customer Account Don Create", ha: "An Ƙirƙiri Asusun Abokin Ciniki", ig: "Emepụtala Akaụntụ Onye Ahịa", yo: "A Ti Ṣẹ̀dá Àkáǹtì Oníbàárà" },
  "ajo.loginCredentialsSentAuto":     { en: "Login credentials sent automatically", pidgin: "We don send login details by themself", ha: "An aika bayanan shiga ta atomatik", ig: "Ezigala nkọwa nbanye na-akpaghị aka", yo: "A ti fi àlàyé ìwọlé ránṣẹ́ fúnra rẹ̀" },
  "ajo.loginEmailSentTo":             { en: "An email with login credentials has been sent to {email}. The client can log in at kudiai.app and will set a permanent password on first login.", pidgin: "We don send email wey get login details to {email}. The customer fit log in for kudiai.app and dem go set permanent password the first time.", ha: "An aika imel mai bayanan shiga zuwa {email}. Abokin ciniki zai iya shiga a kudiai.app kuma zai saita kalmar sirri ta dindindin a shigarsa ta farko.", ig: "Ezigala email nwere nkọwa nbanye na {email}. Onye ahịa nwere ike ịbanye na kudiai.app ma ga-edobe paswọọdụ na-adịgide adịgide na nbanye mbụ.", yo: "A ti fi ímeèlì pẹ̀lú àlàyé ìwọlé ránṣẹ́ sí {email}. Oníbàárà lè wọlé ní kudiai.app yóò sì ṣètò ọ̀rọ̀ aṣínà títí láé nígbà àkọ́kọ́ tó bá wọlé." },
  "ajo.passwordReset":                { en: "Password Reset", pidgin: "Password Reset", ha: "Sake Saita Kalmar Sirri", ig: "Ntọgharị Paswọọdụ", yo: "Àtúntò Ọ̀rọ̀ Aṣínà" },
