  "ajo.membershipNo":                 { en: "Membership No.", pidgin: "Membership No.", ha: "Lambar Memba", ig: "Nọmba Onye Otu", yo: "Nọ́ńbà Ọmọ Ẹgbẹ́" },
  "ajo.shareNewCredentials":          { en: "Share these new credentials with the client. They can log in at kudiai.app and will set a permanent password on first login.", pidgin: "Share these new login details with the customer. Dem fit log in for kudiai.app and dem go set permanent password the first time.", ha: "Raba waɗannan sabbin bayanan shiga da abokin ciniki. Zai iya shiga a kudiai.app kuma zai saita kalmar sirri ta dindindin a shigarsa ta farko.", ig: "Kesaa nkọwa nbanye ọhụrụ ndị a na onye ahịa. Ha nwere ike ịbanye na kudiai.app ma ga-edobe paswọọdụ na-adịgide adịgide na nbanye mbụ.", yo: "Pín àlàyé ìwọlé tuntun yìí pẹ̀lú oníbàárà. Wọ́n lè wọlé ní kudiai.app wọn yóò sì ṣètò ọ̀rọ̀ aṣínà títí láé nígbà àkọ́kọ́ tí wọ́n bá wọlé." },
  "ajo.rejectSecurityHeldWithdrawal": { en: "Reject Security-Held Withdrawal", pidgin: "Reject Withdrawal Wey Security Hold", ha: "Ƙi Cire Kuɗin da Aka Riƙe don Tsaro", ig: "Jụ Mwepụ Ego E Jidere Maka Nchekwa", yo: "Kọ Ìyọwó Tí A Dá Dúró Fún Ààbò" },
  "ajo.rejectingRequestOf":           { en: "Rejecting {name}'s request of {amount}. The client will be notified with your reason.", pidgin: "You dey reject {name} request of {amount}. We go tell the customer your reason.", ha: "Ana ƙin buƙatar {name} ta {amount}. Za a sanar da abokin ciniki dalilinka.", ig: "A na-ajụ arịrịọ {name} nke {amount}. A ga-agwa onye ahịa ihe kpatara gị.", yo: "Ò ń kọ ìbéèrè {name} ti {amount}. A ó sọ ìdí rẹ fún oníbàárà." },
  "ajo.heldRejectPlaceholder":        { en: "e.g. Security review period has not elapsed — please retry in 24h…", pidgin: "e.g. Security check time never finish — abeg try again after 24h…", ha: "misali: Lokacin binciken tsaro bai ƙare ba — da fatan a sake gwadawa bayan awa 24…", ig: "dịka: Oge nyocha nchekwa agafebeghị — biko nwaa ọzọ n'ime awa 24…", yo: "àpẹẹrẹ: Àsìkò àyẹ̀wò ààbò kò tíì parí — jọ̀wọ́ tún gbìyànjú lẹ́yìn wákàtí 24…" },
