  "ajo.rejectingClaimOf":             { en: "Rejecting {name}'s claim of {amount}. The client will be notified with your reason.", pidgin: "You dey reject {name} claim of {amount}. We go tell the customer your reason.", ha: "Ana ƙin iƙirarin {name} na {amount}. Za a sanar da abokin ciniki dalilinka.", ig: "A na-ajụ nkwupụta {name} nke {amount}. A ga-agwa onye ahịa ihe kpatara gị.", yo: "Ò ń kọ ẹ̀tọ́ {name} ti {amount}. A ó sọ ìdí rẹ fún oníbàárà." },
