  "ajo.archivingGroupWarnOne":        { en: "Archiving {name} will remove it from active use and detach all {n} member. This requires admin approval and cannot be reversed through the portal. All contribution records, rounds, and payout history are preserved.", pidgin: "If you archive {name}, e go comot from active use and remove all {n} member. E need admin approval and you no fit reverse am for portal. All contribution records, rounds, and payout history go still dey.", ha: "Ajiye {name} a gefe zai cire shi daga amfani kuma ya raba duk membobi {n}. Wannan yana buƙatar amincewar mai kula kuma ba za a iya juyar da shi ta portal ba. Duk bayanan ajiya, zagaye, da tarihin biya za a adana su.", ig: "Idowe {name} n'akụkọ ga-ewepụ ya n'ọrụ ma kewapụ onye otu {n} niile. Nke a chọrọ nkwado onye nchịkwa ma enweghị ike ịtụgharị ya site na portal. A ga-echekwa ndekọ ntinye ego niile, okirikiri, na akụkọ ịkwụ ụgwọ.", yo: "Fífi {name} pamọ́ yóò yọ ọ́ kúrò nínú lílò, yóò sì ya gbogbo ọmọ ẹgbẹ́ {n} kúrò. Èyí nílò ìfọwọ́sí alábòójútó, a kò sì lè yí i padà nínú portal. Gbogbo àkọsílẹ̀ ìdáwó, àyíká, àti ìtàn ìsanwó ni a ó pa mọ́." },
  "ajo.archivingGroupWarnMany":       { en: "Archiving {name} will remove it from active use and detach all {n} members. This requires admin approval and cannot be reversed through the portal. All contribution records, rounds, and payout history are preserved.", pidgin: "If you archive {name}, e go comot from active use and remove all {n} members. E need admin approval and you no fit reverse am for portal. All contribution records, rounds, and payout history go still dey.", ha: "Ajiye {name} a gefe zai cire shi daga amfani kuma ya raba duk membobi {n}. Wannan yana buƙatar amincewar mai kula kuma ba za a iya juyar da shi ta portal ba. Duk bayanan ajiya, zagaye, da tarihin biya za a adana su.", ig: "Idowe {name} n'akụkọ ga-ewepụ ya n'ọrụ ma kewapụ ndị otu {n} niile. Nke a chọrọ nkwado onye nchịkwa ma enweghị ike ịtụgharị ya site na portal. A ga-echekwa ndekọ ntinye ego niile, okirikiri, na akụkọ ịkwụ ụgwọ.", yo: "Fífi {name} pamọ́ yóò yọ ọ́ kúrò nínú lílò, yóò sì ya gbogbo ọmọ ẹgbẹ́ {n} kúrò. Èyí nílò ìfọwọ́sí alábòójútó, a kò sì lè yí i padà nínú portal. Gbogbo àkọsílẹ̀ ìdáwó, àyíká, àti ìtàn ìsanwó ni a ó pa mọ́." },
  "ajo.reasonForArchiveReq":          { en: "Reason for archive *", pidgin: "Why you wan archive am *", ha: "Dalilin ajiyewa a gefe *", ig: "Ihe kpatara idowe n'akụkọ *", yo: "Ìdí ìpamọ́ *" },
  "ajo.whyArchiveGroup":              { en: "Why do you need to archive this group?", pidgin: "Why you need archive this group?", ha: "Me yasa kake buƙatar ajiye wannan ƙungiya a gefe?", ig: "Gịnị mere ị chọrọ idowe otu a n'akụkọ?", yo: "Kí ló dé tí o fi fẹ́ fi ẹgbẹ́ yìí pamọ́?" },
  "ajo.submitArchiveRequest":         { en: "Submit Archive Request", pidgin: "Send Archive Request", ha: "Aika Buƙatar Ajiyewa", ig: "Ziga Arịrịọ Idowe", yo: "Fi Ìbéèrè Ìpamọ́ Ránṣẹ́" },
  "ajo.groupCannotArchiveYet":        { en: "This group cannot be archived yet:", pidgin: "You no fit archive this group yet:", ha: "Ba za a iya ajiye wannan ƙungiya a gefe ba tukuna:", ig: "A pụghị idowe otu a n'akụkọ ugbu a:", yo: "A kò lè fi ẹgbẹ́ yìí pamọ́ síbẹ̀:" },
