  "ajo.closeRoundBeforeArchive":      { en: "Close the current round in the Rotation Dashboard before requesting archive.", pidgin: "Close the round wey dey now for Rotation Dashboard before you ask to archive.", ha: "Rufe zagayen yanzu a Allon Juyawa kafin neman ajiyewa.", ig: "Mechie okirikiri ugbu a na Dashboard Ntụgharị tupu ị rịọ idowe.", yo: "Ti àyíká lọ́wọ́lọ́wọ́ nínú Pátákó Yíyípo kí o tó béèrè ìpamọ́." },
  "ajo.nMemberUnsettledOne":          { en: "{n} member with unsettled balance", pidgin: "{n} member still get money wey never settle", ha: "Memba {n} yana da ragowar kuɗi da ba a daidaita ba", ig: "Onye otu {n} nwere ego a kwụbeghị", yo: "Ọmọ ẹgbẹ́ {n} ní owó tí a kò tíì yanjú" },
  "ajo.nMembersUnsettledMany":        { en: "{n} members with unsettled balance", pidgin: "{n} members still get money wey never settle", ha: "Membobi {n} suna da ragowar kuɗi da ba a daidaita ba", ig: "Ndị otu {n} nwere ego a kwụbeghị", yo: "Ọmọ ẹgbẹ́ {n} ní owó tí a kò tíì yanjú" },
  "ajo.allBalancesWithdrawnFirst":    { en: "All member balances must be withdrawn before archiving.", pidgin: "Everybody must withdraw their money before you archive.", ha: "Dole a cire duk kuɗin membobi kafin ajiyewa a gefe.", ig: "A ga-ewepụrịrị ego ndị otu niile tupu idowe n'akụkọ.", yo: "Gbogbo owó ọmọ ẹgbẹ́ gbọ́dọ̀ jẹ́ yíyọ kí a tó fi pamọ́." },
