  "ajo.rot.addMembersFirst":     { en: "Add members to the group first", pidgin: "Add members to the group first", ha: "Ƙara mambobi a ƙungiyar tukuna", ig: "Buru ụzọ tinye ndị otu n'otu ahụ", yo: "Kọ́kọ́ fi àwọn ọmọ ẹgbẹ́ kún ẹgbẹ́ náà" },
