  "ajo.rot.startFailed":         { en: "Failed to start round", pidgin: "Round no gree start", ha: "An kasa fara zagaye", ig: "Ịmalite okirikiri adaghị", yo: "Kò ṣeé ṣe láti bẹ̀rẹ̀ ìyípo" },
