  "ajo.profile.requestSubmittedBody": { en: "The admin team will review and action this shortly. The client card will show a pending badge until resolved.", pidgin: "Admin team go check am soon. The client card go show pending until dem settle am.", ha: "Ƙungiyar gudanarwa za ta duba ta ɗauki mataki nan ba da jimawa ba. Katin abokin ciniki zai nuna alamar jira har sai an warware.", ig: "Ndị admin ga-enyocha ma mee ihe n'oge na-adịghị anya. Kaadị onye ahịa ga-egosi akara na-echere ruo mgbe edozịrị ya.", yo: "Ẹgbẹ́ alábòójútó yóò ṣàyẹ̀wò rẹ̀ láìpẹ́. Káàdì oníbàárà yóò fi àmì ìdúró hàn títí a ó fi yanjú rẹ̀." },
  "ajo.profile.balanceMustBeZeroRequest": { en: "Balance must be ₦0.00 before requesting archive. Current balance: {balance}. Record a settling withdrawal first.", pidgin: "Balance must be ₦0.00 before you fit ask for archive. Balance now: {balance}. Record withdrawal wey go clear am first.", ha: "Dole ragowar kuɗi ya zama ₦0.00 kafin neman adanawa. Ragowar yanzu: {balance}. Rubuta cirewar da za ta share shi tukuna.", ig: "Ego fọdụrụ ga-abụ ₦0.00 tupu ịrịọ ka edobe ya. Ego fọdụrụ ugbu a: {balance}. Buru ụzọ dee mwepụ ga-ekpochapụ ya.", yo: "Owó tó kù gbọdọ̀ jẹ́ ₦0.00 kí o tó béèrè ìpamọ́. Owó tó kù báyìí: {balance}. Kọ́kọ́ kọ ìgbowó tí yóò pa á rẹ́ sílẹ̀." },
  "ajo.profile.balanceMustBeZeroArchive": { en: "Balance must be ₦0.00 before archiving. Current balance: {balance}. Record a settling withdrawal first.", pidgin: "Balance must be ₦0.00 before you fit archive. Balance now: {balance}. Record withdrawal wey go clear am first.", ha: "Dole ragowar kuɗi ya zama ₦0.00 kafin adanawa. Ragowar yanzu: {balance}. Rubuta cirewar da za ta share shi tukuna.", ig: "Ego fọdụrụ ga-abụ ₦0.00 tupu edobe ya. Ego fọdụrụ ugbu a: {balance}. Buru ụzọ dee mwepụ ga-ekpochapụ ya.", yo: "Owó tó kù gbọdọ̀ jẹ́ ₦0.00 kí o tó pa á mọ́. Owó tó kù báyìí: {balance}. Kọ́kọ́ kọ ìgbowó tí yóò pa á rẹ́ sílẹ̀." },
  "ajo.profile.requestClientArchive": { en: "Request Client Archive", pidgin: "Ask make dem archive client", ha: "Nemi adana abokin ciniki", ig: "Rịọ ka edobe onye ahịa", yo: "Béèrè ìpamọ́ oníbàárà" },
  "ajo.profile.requestArchiveFor":   { en: "Request archive for {name}?", pidgin: "Ask make dem archive {name}?", ha: "Nemi adana {name}?", ig: "Rịọ ka edobe {name}?", yo: "Béèrè ìpamọ́ fún {name}?" },
