  "ajo.profile.totalWithdrawn":      { en: "Total withdrawn:", pidgin: "Total withdraw:", ha: "Jimillar cirewa:", ig: "Ngụkọta ewepụrụ:", yo: "Àpapọ̀ ìgbowó:" },
  "ajo.profile.balanceConfirmedZero": { en: "Balance confirmed ₦0.00", pidgin: "Balance na ₦0.00", ha: "An tabbatar ragowa ₦0.00", ig: "Ekwenyela na ego fọdụrụ bụ ₦0.00", yo: "A ti jẹ́rìísí owó tó kù ₦0.00" },
  "ajo.profile.archiveRequestNote":  { en: "The request will be reviewed by an admin. The client card will show \"Archive pending admin approval\" until a decision is made. All contribution history is preserved.", pidgin: "Admin go check the request. The client card go show \"Archive pending admin approval\" until dem decide. All contribution history go still dey.", ha: "Mai gudanarwa zai duba buƙatar. Katin abokin ciniki zai nuna \"Adanawa na jiran amincewar admin\" har sai an yanke shawara. Za a adana duk tarihin ajiya.", ig: "Onye admin ga-enyocha arịrịọ ahụ. Kaadị onye ahịa ga-egosi \"Ndobe na-echere nkwado admin\" ruo mgbe e kpebiri. A ga-echekwa akụkọ ntinye ego niile.", yo: "Alábòójútó yóò ṣàyẹ̀wò ìbéèrè náà. Káàdì oníbàárà yóò fi \"Ìpamọ́ ń dúró de ìfọwọ́sí admin\" hàn títí a ó fi ṣe ìpinnu. Gbogbo ìtàn ìdáwó yóò wà síbẹ̀." },
